using ResilienceAdmissionLab;
using Xunit;
public sealed class ResilienceTests { [Fact] public async Task Transient_failure_retries_with_bound() { var calls = 0; var result = await new RetryPolicy(3, _ => TimeSpan.Zero).ExecuteAsync<string>((_, _) => ++calls < 3 ? ValueTask.FromException<string>(new TransientException("x")) : ValueTask.FromResult("ok"), x => x is TransientException); Assert.Equal("ok", result); Assert.Equal(3, calls); } [Fact] public async Task Permanent_failure_is_not_retried() { var calls = 0; await Assert.ThrowsAsync<InvalidOperationException>(async () => await new RetryPolicy(3, _ => TimeSpan.Zero).ExecuteAsync<string>((_, _) => { calls++; return ValueTask.FromException<string>(new InvalidOperationException()); }, x => x is TransientException)); Assert.Equal(1, calls); } [Fact] public void Bucket_rejects_after_capacity() { var b = new TokenBucket(2, 0, TimeProvider.System); Assert.True(b.TryAcquire()); Assert.True(b.TryAcquire()); Assert.False(b.TryAcquire()); } [Fact] public void Bucket_refills_with_time() { var t = new FakeTimeProvider(); var b = new TokenBucket(1, 1, t); Assert.True(b.TryAcquire()); Assert.False(b.TryAcquire()); t.Advance(TimeSpan.FromSeconds(1)); Assert.True(b.TryAcquire()); } private sealed class FakeTimeProvider : TimeProvider { private DateTimeOffset now = DateTimeOffset.UnixEpoch; public override DateTimeOffset GetUtcNow() => now; public void Advance(TimeSpan value) => now += value; } }
